@@ -1690,200 +1690,204 @@ gnutls_pkcs12_simple_parse(gnutls_pkcs12_t p12,
                                                gnutls_realloc_fast
                                                (_extra_certs,
                                                 sizeof(_extra_certs
                                                        [0]) *
                                                 ++_extra_certs_len);
                                        if (!_extra_certs) {
                                                gnutls_assert();
                                                ret =
                                                        GNUTLS_E_MEMORY_ERROR;
                                                goto done;
                                        }
                                        _extra_certs
                                                [_extra_certs_len -
                                                 1] = this_cert;
                                        this_cert = NULL;
                                } else {
                                        if (chain && _chain_len == 0) {
                                                _chain =
                                                    gnutls_malloc(sizeof
                                                                  (_chain
                                                                   [0]) *
                                                                  (++_chain_len));
                                                if (!_chain) {
                                                        gnutls_assert();
                                                        ret =
                                                            GNUTLS_E_MEMORY_ERROR;
                                                        goto done;
                                                }
                                                _chain[_chain_len - 1] =
                                                    this_cert;
                                                this_cert = NULL;
                                        } else {
                                                gnutls_x509_crt_deinit
                                                    (this_cert);
                                        }
                                }
                                break;

                        case GNUTLS_BAG_CRL:
                                if (crl == NULL || *crl != NULL) {
                                        gnutls_assert();
                                        break;
                                }

                                ret = gnutls_x509_crl_init(crl);
                                if (ret < 0) {
                                        gnutls_assert();
                                        goto done;
                                }

                                ret =
                                    gnutls_x509_crl_import(*crl, &data,
